    &__note {
        margin-top: .4rem;
        font-size: .65rem;
        color: @con-cyan;

        &--muted { color: @con-text-dim; }
    }

    &__info {
        display: flex;
        flex-direction: column;
        gap: .7rem;
        min-width: 0;
    }
    &__block {
        padding: .6rem .7rem;
        border-radius: .5rem;
        background: rgba(255, 255, 255, 0.035);
        box-shadow: inset 0 0 0 .05rem rgba(255, 255, 255, 0.08);
    }
    &__benefit {
        display: flex;
        align-items: center;
        gap: .6rem;
    }
    &__benefit-glyph {
        display: inline-flex;
        zoom: calc(1.25 * var(--con-ui-scale, 1));
        flex: 0 0 auto;
        min-width: 2.2rem;
        justify-content: center;
    }
    &__benefit-desc {
        font-size: .7rem;
