    }
    &__pulse-bar {
        display: block;
        width: 40%;
        height: 100%;
        border-radius: 49.95rem;
        background: linear-gradient(90deg, transparent, fade(@con-cyan, 85%), transparent);
        animation: con-load-pulse calc(1600ms * var(--motion-scale, 1)) ease-in-out infinite;
    }
    &__error {
        font-size: .95rem;
        color: #ffc9c4;
        padding: .4rem .8rem;
        border-radius: .5rem;
        background: fade(@con-red, 10%);
        box-shadow: inset 0 0 0 .05rem fade(@con-red, 55%);
